import { useEffect, useId, useRef } from "react";
import type { KeyboardEvent, MouseEvent } from "react";
import "./ConfirmDialog.css";

export interface ConfirmDialogProps {
  open: boolean;
  noteTitle: string;
  onCancel: () => void;
  onConfirm: () => void;
}

export function ConfirmDialog({
  open,
  noteTitle,
  onCancel,
  onConfirm,
}: ConfirmDialogProps) {
  const titleId = useId();
  const descriptionId = useId();
  const cancelRef = useRef<HTMLButtonElement>(null);
  const deleteRef = useRef<HTMLButtonElement>(null);

  // Keep the latest onCancel in a ref so the focus effect below
  // does not re-run (and re-steal focus) when the parent re-renders.
  const onCancelRef = useRef(onCancel);
  useEffect(() => {
    onCancelRef.current = onCancel;
  }, [onCancel]);

  // On open: remember the previously focused element, move focus to the
  // safe default (Cancel), listen for Escape. On close: restore focus.
  useEffect(() => {
    if (!open) return;

    const previouslyFocused =
      document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null;

    cancelRef.current?.focus();

    const handleDocumentKeyDown = (event: globalThis.KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        onCancelRef.current();
      }
    };

    document.addEventListener("keydown", handleDocumentKeyDown);

    return () => {
      document.removeEventListener("keydown", handleDocumentKeyDown);
      previouslyFocused?.focus();
    };
  }, [open]);

  if (!open) {
    return null;
  }

  // Only two focusable controls exist, so cycling between them
  // fully traps keyboard focus inside the dialog.
  const handleDialogKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key !== "Tab") return;

    const first = cancelRef.current;
    const last = deleteRef.current;
    if (!first || !last) return;

    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  };

  // Clicking the backdrop (not the dialog itself) dismisses the dialog.
  const handleBackdropMouseDown = (event: MouseEvent<HTMLDivElement>) => {
    if (event.target === event.currentTarget) {
      onCancel();
    }
  };

  return (
    <div
      className="confirm-dialog-backdrop"
      onMouseDown={handleBackdropMouseDown}
    >
      <div
        role="alertdialog"
        aria-modal="true"
        aria-labelledby={titleId}
        aria-describedby={descriptionId}
        className="confirm-dialog"
        onKeyDown={handleDialogKeyDown}
      >
        <h2 id={titleId} className="confirm-dialog__title">
          Delete note?
        </h2>
        <p id={descriptionId} className="confirm-dialog__body">
          <span aria-hidden="true">&ldquo;</span>
          <strong className="confirm-dialog__note-title">{noteTitle}</strong>
          <span aria-hidden="true">&rdquo;</span> will be permanently deleted.
          This can&rsquo;t be undone.
        </p>
        <div className="confirm-dialog__actions">
          <button
            ref={cancelRef}
            type="button"
            className="confirm-dialog__button confirm-dialog__button--cancel"
            onClick={onCancel}
          >
            Cancel
          </button>
          <button
            ref={deleteRef}
            type="button"
            className="confirm-dialog__button confirm-dialog__button--danger"
            onClick={onConfirm}
          >
            Delete
          </button>
        </div>
      </div>
    </div>
  );
}
