  --confirm-focus: #8fd1bd;
}

.confirm-dialog-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: var(--confirm-backdrop);
  animation: confirm-dialog-fade 160ms ease-out;
}

.confirm-dialog {
  box-sizing: border-box;
  width: min(420px, 100%);
  padding: 28px 28px 24px;
  border: 1px solid var(--confirm-border);
  border-radius: 16px;
  background: var(--confirm-surface);
  box-shadow: var(--confirm-shadow);
  color: var(--confirm-text);
  font-family: inherit;
  animation: confirm-dialog-rise 200ms ease-out;
}

.confirm-dialog__title {
  margin: 0 0 10px;
  font-size: 1.25rem;
  font-weight: 600;
  line-height: 1.3;
}

.confirm-dialog__body {
  margin: 0 0 24px;
  font-size: 0.95rem;
  line-height: 1.5;
  color: var(--confirm-muted);
  overflow-wrap: anywhere;
}

.confirm-dialog__note-title {
  color: var(--confirm-text);
  font-weight: 600;
}

.confirm-dialog__actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
}

.confirm-dialog__button {
  min-width: 96px;
  padding: 10px 18px;
  border-radius: 999px;
  font: inherit;
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition:
    background-color 120ms ease,
    border-color 120ms ease,
    color 120ms ease;
}

.confirm-dialog__button--cancel {
  border: 1px solid var(--confirm-cancel-border);
  background: var(--confirm-cancel-bg);
  color: var(--confirm-cancel-text);
}

.confirm-dialog__button--cancel:hover {
  background: var(--confirm-cancel-hover);
}

.confirm-dialog__button--danger {
  border: 1px solid transparent;
  background: var(--confirm-danger-bg);
  color: var(--confirm-danger-text);
}

.confirm-dialog__button--danger:hover {
  background: var(--confirm-danger-bg-hover);
}

.confirm-dialog__button:focus-visible {
  outline: 2px solid var(--confirm-focus);
  outline-offset: 3px;
}

@keyframes confirm-dialog-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes confirm-dialog-rise {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .confirm-dialog-backdrop,
  .confirm-dialog {
    animation: none;
  }

  .confirm-dialog__button {
    transition: none;
  }
}
